for (const name of CONTAINERS) {
  test(`${name} matches the Python parser field for field`, skipUnlessGolden(name), () => {
    // Parsed exactly as the file sits on disk, no EZHex unwrapping, which is what puts
    // `blob_offset` and every `file_offset` inside the comparison. Confusing a blob offset with a
    // file offset is a mistake that has already cost time on this project.
    const container = parse(load(name) as Uint8Array);
    assert.deepEqual(summary(container), goldenVector(name));
  });
}

/**
 * The checks every golden vector carries, by name. Listed rather than counted, because a count
 * cannot tell a vector that lost `trailer_checksum_recomputes` from one that gained a check nobody
 * asked for, and the count is what stood here as a floor of seven against a real fifteen.
 */
const UNIVERSAL_CHECKS = [
  'end_addr_points_at_end_marker',
  'flash_base_is_block_aligned',
  'format_high_half_is_zero',
  'last_section_is_null',
  'marker_as_expected_for_family',
  'format_states_the_pointer_count',
  'section_spare_bytes_are_zero',
  'section_table_ends_at_the_marker',
  'sections_ascend',
  'sections_within_blob',
  'slot0_is_a_feed_frame',
  'slot1_states_the_architecture',
  'slot3_is_a_timestamp',
  'trailer_checksum_recomputes',
];

test('the vectors carry the fields worth comparing, rather than being nearly empty', () => {
  // Guards the comparison itself. A vector reduced to a couple of scalars, or a summary that
  // quietly stopped emitting sections, would let every test above pass while checking almost
  // nothing.
  const present = CONTAINERS.map(goldenVector).filter((v) => v !== undefined);
  if (present.length === 0) return; // no lab: the skips above have already said so
  let complete = 0;
  for (const vector of present) {
    for (const field of ['flash_base', 'end_addr', 'pointer_count', 'trailer_checksum']) {
      assert.ok(field in vector, `vector is missing ${field}`);
    }
    // The section count is the vector's own `pointer_count` and not a floor of nineteen. That is
    // stronger than any literal here, because it is a closure between two fields the Python side
    // emitted separately: a summary that stopped emitting sections would have to corrupt the count
    // in the same direction to pass, and the four values it takes, 20 to 23, are the four pointer
    // table lengths in the corpus rather than a number this file chose.
    const sections = vector['sections'] as unknown[];
    assert.ok(Array.isArray(sections), 'a vector has no section table');
    assert.equal(sections.length, vector['pointer_count'], 'one section per pointer slot');
    // And the checks by name, not by count. Fourteen are on every vector; `key_table_is_complete`
    // needs a key table, so it is on 37 of the 41 and the four without one are asserted below.
    const checks = Object.keys(vector['checks'] as object);
    for (const name of UNIVERSAL_CHECKS) assert.ok(checks.includes(name), `no ${name} check`);
    assert.ok(checks.every((n) => n === 'key_table_is_complete' || UNIVERSAL_CHECKS.includes(n)),
      `an unexpected check: ${checks.filter((n) => n !== 'key_table_is_complete' && !UNIVERSAL_CHECKS.includes(n)).join(', ')}`);
    if (checks.includes('key_table_is_complete')) complete += 1;
  }
  // 42 since 26 August 2026: the Harmony 895, the first arch 10 container with a known answer,
  // section 178. 41 before it, when the phase 7 pair landed, section 174. 45 since the two regions
  // Logitech's own client read off the spare Harmony One, section 215, which are deliberately
  // duplicates of vectors already here.
  // 46 since `one_spare_20260830`, 30 August 2026, and unlike the pair before it this one is not a
  // duplicate of anything: it is a configuration nothing here had seen.
  // 47 since the read taken after the first write, section 222, which **is** a duplicate of that one
  // and is kept for exactly that: a vector that stopped matching would say the write changed
  // something.
  // 48 since the read taken after the first write that **changed** something, section 236, which is
  // a duplicate of both for the same reason and for a sharper one: two operands on the remote are
  // deliberately not what a vector carries, so this one matching says the edit stayed where it was
  // aimed.
  // 55 since the region read taken once the second device write was finished, section 246, which
  // is a duplicate of the mid write one above except in the block that write completed.
  // 56 since the write of section 247, whose vector differs from the one above in the one delay
  // the write raised, which is the only field a vector carries that the edit touched.
  // 57 since the revert of section 248.
  // 58 since the programmed Harmony 350, section 262, the first configuration this project has read
  // off a remote of the file based family.
  // 59 since the one device differential, section 263.
  // 61 since that Harmony 300 was programmed, section 265.
  // 62 since the Harmony 525's erase block, section 268, the first region read of a remote other
  // than the spare Harmony One.
  // 63 since the spare Harmony One's region was read again after the first activity write, section
  // 276, because that write invalidated the dump every later write compares against.
  // 64 since the compare base for the third activity write, section 277.
  // 68 since the compare base for the working screen write, section 279.
  // 69 since the compare base for the power off write, section 280.
  // 70 since the Harmony 650's configuration region, section 282, the first arch 14 compare base.
  // 71 since that region after 1.4.2's delay write, 72 since the region after 1.4.3's composed device,
  // 73 since the region after section 286's tour skip, 74 and 75 since the reads either side of
  // 1.4.4's composed activity, section 291, and 76 and 77 since the screen light timer at 20 and at
  // 10, section 292, and 78 since the spare Harmony One's region before its four page menu, 293,
  // and 79 since the 650's region after LG kijken's own device list, 294, and 80 since the Harmony
  // 700's external flash, whose container duplicates `h700_gspm`'s, 295, and 81 since the same range
  // after section 296's sync, and 83 since section 297's blank and 2.8 staged regions, and 84 since the staging read
  // before that sync, and 85 since the 700's configuration region on 2.8, and 86 since
  // that region after section 300's write, and 88 since the reads after section 301's delay write
  // and its revert, and 89 since the Harmony 600's region before its first write, and 90
  // since that region after section 302's write, and 92 since its two external flash reads from
  // 0x000000, which parse to the safe mode container, and 93 since the region after its KPN delay write,
  // and 94 since that region put back, section 303, and 95 since the Harmony 650's configuration after
  // the Panasonic television was added to it, section 305.
  // 97 since section 306's two compiles with the power hold test devices, 100 since 307's three, 101 since
  // 308's one, 102 since the 650's region before section 309's test device, 103 since the one after it.
  // 112 with the 650's eight bench compare bases after the seventh device and section NNN's third
  // bench configuration, which had been registered without a vector.
  assert.equal(present.length, 112, 'every vector, which is what `make golden` compares');
  // 38 since the Harmony 895 landed: its key table reads with the existing reader even though
  // every other arch 10 reader is gated, which is what made section 177's keypad closure possible
  // without any arch 10 progress at all.
  // 39 since the Harmony 350, section 194: an arch 16 container's key table reads with the existing
  // reader, the same way the Harmony 895's did, which is a property of the reader and not of a mapping.
  // 41 since section 215's pair, both of which have one: the user config duplicates
  // `one_spare_before_sync` and the embedded one duplicates `one_safemode`.
  // 42 since `one_spare_20260830`, an ordinary arch 12 container read off a Harmony One, and 43 since
  // the read taken after the first write, which duplicates it. 44 since the read taken after the
  // first write that changed something, which duplicates it too. 50 since the two states the device
  // writes of 3 September 2026 left that unit in, section 242, whose containers this project's own
  // composer assembled: they carry a key table like any other and are the first vectors here that
  // check our own output rather than Logitech's.
  // 51 since that mid write state finished, section 246, which carries the same key table.
  // 52 since section 247, which changed a delay and no key binding.
  // 54 since the programmed Harmony 350, section 262. Its key table reads with the existing reader,
  // which is worth a line because that architecture's fifteen slots are not the base twenty with
  // insertions and almost nothing else about it transfers by index.
  // 55 since the one device differential, section 263.
  // 56 since the Harmony 300, section 264, whose key table reads with the existing reader.
  // 58 since the spare Harmony One's region read after the first activity write, section 276: its
  // key table reads normally, which is worth a line because the header defect that write corrected
  // is in base slot 13 and touches nothing a key table reader looks at.
  // 59 since the compare base for the third activity write, section 277.
  // 63 since the compare base for the working screen write, section 279.
  // 64 since the compare base for the power off write, section 280.
  // 65 since the Harmony 650's configuration region, section 282.
  // 66 since that region after 1.4.2's delay write.
  // 67 since that region after 1.4.3's composed device, section 285, which carries its key table
  // unchanged: the composer adds a device mode and menu entries and no key table entry.
  // 68 since the region after section 286's tour skip, which changes one action list instruction.
  // 70 since the reads either side of 1.4.4's composed activity, section 291, and 71 since the screen
  // light timer at 20 seconds, section 292, 72 since it at 10, and 73 since the spare's region
  // before its four page menu, section 293, and 74 since the 650's after section 294: each keeps a
  // key table. 75 since the Harmony 700's external flash, section 295, whose container is
  // `h700_gspm`'s and has its key table, and 76 since that range after section 296's sync, and 78
  // since section 297's two, and 79 since the read before that sync, and 80 since the 700's
  // configuration region on 2.8, and 81 since that region after section 300's write, and 83 since the
  // two after section 301's delay write and its revert, and 84 since the Harmony 600's region, and 85
  // since that region after section 302's write, and 87 since its two reads from 0x000000, and 88
  // since the region after its KPN delay write, and 89 since that region put back, and 90 since the
  // Harmony 650's configuration with the Panasonic television, section 305.
  // 92 since section 306's two compiles, 95 since 307's three, 96 since 308's one, 97 since
  // the 650's region before section 309's test device, 98 since the one after it.
  // 107 with the 650's eight bench compare bases and section NNN's third bench configuration.
  assert.equal(complete, 107, 'the vectors whose container has a key table at all');

  // **The number sender field, and why it needs its own guard.** It is an empty array on 30 vectors
  // and null on 8, with eight carrying a record since 30 August 2026, and this comment said 25 and 9
  // while the assertions below said 28 and 8, which is
  // prose drifting away from the numbers beside it. A summary that stopped emitting the field would
  // break nothing anybody would notice:
  // every comparison would still pass, and the two vectors where the two implementations are actually
  // compared on a record would go quiet. Same shape as section 148's hollow claim, where a count of
  // what a reader looked for could not see what it never looked at.
  const senders = present.map((v) => v['number_senders'] as unknown[] | null);
  assert.equal(senders.every((one) => one !== undefined), true, 'a vector is missing number_senders');
  // **7 since arch 10 was switched on**, section 184, down from 10. The three that moved are exactly
  // the three arch 10 reads whose trailer checksum recomputes: base slot 16 is aligned now, so those
  // containers answer the question and the answer is an empty array. The five still null are damaged
  // reads of one Harmony 890, section 122, plus the two containers found inside arch 8 firmware
  // images, which report architecture 0 and have no alignment at all.
  // 8 since the Harmony 350, section 194: arch 16 has no slot mapping, so base slot 16 is not
  // readable on it, which is the same gate arch 10 sat behind before section 184.
  // **Back to 7 since section 262**, and the gate opened the same way arch 10's did: base slot 16 is
  // on arch 16's map, so both its containers answer instead of refusing, and neither of the two
  // arriving cancels the one leaving. What is left is the five damaged arch 10 reads and the two
  // containers found inside arch 8 firmware images.
  assert.equal(senders.filter((one) => one === null).length, 7, 'the containers with no readable slot');
  // 30 since section 215's pair, both of which declare none, like the two vectors they duplicate.
  // 31 since the factory Harmony 350, section 262: it left the unreadable column above rather than
  // arriving, since arch 16's base slot 16 is mapped now, and the answer it gives is a count of zero.
  // 32 since the Harmony 300, section 264: its previous owner set no favourite channels.
  // 33 since the Harmony 525's erase block, section 268, and this one says nothing new about any
  // remote: the block's first 51195 bytes are `h525_config_2` exactly, so it necessarily declares
  // whatever that container declares. It is in the golden population because the two codecs should
  // be compared wherever they can be, not because it is a second sample.
  // 34 since the Harmony 650's configuration region, section 282: its MyHarmony configuration
  // declares no number sender.
  // 35 since that region after 1.4.2's delay write, the same configuration with one delay changed.
  // 36 since that region after 1.4.3's composed device, section 285, which adds none either, and 37
  // since the region after section 286's tour skip, 39 since the reads either side of 1.4.4's
  // composed activity, section 291, and 40 and 41 since the screen light timer at 20 and at 10. The
  // spare's region before its four page menu, section 293, carries a number sender, so not 42; 42
  // since the 650's region after section 294, which carries none, and 43 since the Harmony 700's
  // external flash, section 295, whose container is `h700_gspm`'s and carries none, and 44 since that
  // range after section 296's sync, and 46 since section 297's two, and 47 since the read before that
  // sync, and 48 since the 700's configuration region on 2.8, and 49 since that region after section 300's write,
  // and 51 since the two after section 301's delay write and its revert, and 52 since the Harmony
  // 600's region, whose container is `h600_config` and declares none, and 53 since that region after
  // section 302's write, and 55 since its two reads from 0x000000, whose safe mode container
  // declares none, and 56 since the region after its KPN delay write, and 57 since it was put back, and
  // 58 since the Harmony 650's configuration with the Panasonic television, which declares none either.
  // 60 since section 306's two compiles, neither of which declares one, and 63 since 307's three, and
  // 64 since 308's one, and 65 since the 650's region before section 309's test device, 66 since the one after it.
  // 75 with the 650's eight bench compare bases and section NNN's third bench configuration, none of
  // which declares one.
  assert.equal(senders.filter((one) => Array.isArray(one) && one.length === 0).length, 75);
  // **Four since the second compiled sample**, and the reason is the account rather than the request:
  // every configuration compiled from the account that carries favourite channels carries the sender
  // record too, whichever appliances are on it that day. Three of them were made deliberately for base
  // slot 16 and this one came with it, section 165.
  // Seven since the phase 7 pair: both compiles come from the account that carries favourite
  // channels, so both carry the sender record, section 174.
  // **Eight since `one_spare_20260830`, and it is not a made config**, which is why the message
  // below no longer says so: it is a read off the spare Harmony One of whatever Logitech's software
  // last synced onto it, and it carries the record for the same reason the compiles do, the account
  // behind it having favourite channels.
  // Nine since the read taken after the first write, which duplicates the one before it: the record
  // survived the erase and the write, which is the same statement as the whole file comparison and
  // is worth having on this field in particular, base slot 16 being the one the two implementations
  // are compared on at all.
  // Ten since the read taken after the first write that changed something, which duplicates it
  // again: the record survived a second erase and write, this one with two bytes deliberately
  // different, so it also says the edit did not disturb a section it was nowhere near.
  // Eleven since the read after the second such write. It survived three erase and write cycles of
  // the same block in the end, since the third put the bytes back, and the whole configuration then
  // read off the remote is byte identical to the dump from before any of them.
  // Sixteen since the two device writes of 3 September 2026, section 242: the spare's favourite
  // channel records come through the composition unchanged, which is worth a line of its own because
  // the composer inserts bytes below them and base slot 16's records state addresses.
  // Seventeen since that state finished, section 246: a third erase and write of the composed
  // configuration's blocks and those records still read the same.
  // Eighteen since section 247, a fourth erase and write of those blocks with the records intact.
  // 20 since the programmed Harmony 350, section 262, and it is the first to populate this section
  // on any architecture but arch 12, so what had looked like a Harmony One mechanism is not one.
  // 21 since the one device differential, section 263: the favourites are on a device that did
  // not move, so the record survives, which is itself the answer to one of that section's questions.
  // 22 since the programmed Harmony 300, section 265, which carries a record for the four favourite
  // channels Danny entered on it.
  // 23 since the spare Harmony One's region read after the first activity write, section 276: its
  // favourite channel records are the same ones, carried through a fifth erase and write of those
  // blocks, which is what makes this count the cheapest evidence that a write preserves them.
  // 24 since the compare base for the third activity write, section 277: the favourite channel
  // records have now survived a sixth erase and write of the blocks holding them.
  // 28 since the compare base for the working screen write, section 279, one erase and write further.
  // 29 since the compare base for the power off write, section 280, and 30 since the one for the
  // four page activity menu write, section 293.
  assert.equal(senders.filter((one) => Array.isArray(one) && one.length > 0).length, 30,
    'the configs that populate base slot 16');
});

test('the list above covers exactly what the Python side writes a vector for', () => {
  // The check that should always have been here. `h525_config_2` sat in `tools/golden.py` and not
  // in this file, so a vector was written and never read, which looks identical to a passing
  // comparison. Parsed out of the tuple rather than imported, since one side is Python.
  const source = readFileSync(join(REPO_ROOT, 'tools', 'golden.py'), 'utf8');
  const block = /^CONTAINERS = \($(.*?)^\)$/ms.exec(source);
  assert.ok(block, 'tools/golden.py has no CONTAINERS tuple in the expected shape');
  const python = [...block[1]!.matchAll(/'([a-z0-9_]+)'/g)].map((m) => m[1] as string);
  // 62 since the Harmony 525's erase block, section 268. A region read belongs in the golden
  // population and not in the corpus one, which is the split every region here takes: the vectors
  // exist to make the two codecs disagree if they can, and the corpus totals count each
  // configuration once.
  // 63 since the spare Harmony One's region was read again after the first activity write, section
  // 276, because that write invalidated the dump every later write compares against.
  // 64 since the compare base for the third activity write, section 277.
  // 68 since the compare base for the working screen write, section 279.
  // 69 since the compare base for the power off write, section 280.
  // 70 since the Harmony 650's configuration region, section 282.
  // 71 since that region after 1.4.2's delay write, the compare base for the revert, and 72 since the
  // region after 1.4.3's composed device, and 73 since the region after section 286's tour skip,
  // 75 since the reads either side of 1.4.4, section 291, 77 since the 20 and 10 second timers, and
  // 78 since the spare's region before its four page menu, section 293, and 79 since the 650's
  // after section 294, and 80 since the Harmony 700's external flash, section 295, and 81 since that
  // range after section 296's sync, and 83 since section 297's two, and 84 since the read before that
  // sync, and 85 since the 700's configuration region on 2.8, and 86 since that
  // region after section 300's write, and 88 since the two after section 301's write and revert, and
  // 89 since the Harmony 600's region before its first write, and 90 since that region after 302's,
  // and 92 since its two external flash reads from 0x000000, and 93 since its KPN delay write, and 94
  // since it was put back, and 95 since the 650's configuration with the Panasonic television.
  // 97 since section 306's two compiles, 100 since 307's three, 101 since 308's one, and 102 since
  // the 650's region before section 309's test device, 103 since its region after it.
  // 112 with the 650's eight bench compare bases and section NNN's third bench configuration.
  assert.equal(python.length, 112, 'the golden vectors, which is what `make golden` prints');
  assert.deepEqual([...CONTAINERS].sort(), python.sort());
});

test('a mutated container does not match its vector', () => {
  // A comparison that cannot fail is not a comparison. Flipping one byte of the format word has
  // to show up, or these tests are asserting that two undefineds are equal.
  const original = load('h700_config');
  const vector = goldenVector('h700_config');
  if (original === undefined || vector === undefined) return;
  const mutated = new Uint8Array(original);
  const formatWord = (parse(original).blobOffset as number) + 8;
  mutated[formatWord + 1] = (mutated[formatWord + 1] as number) ^ 0x01;
  assert.notDeepEqual(summary(parse(mutated)), vector);
});
